package com.beeboee.magnot.material;import net.minecraft.tags.ItemTags;import net.minecraft.util.ResourceLocation;import net.minecraftforge.fml.ModList;public final class AdaptiveMaterials{private static final ResourceLocation DUST=new ResourceLocation("forge","dusts/iron");private AdaptiveMaterials(){}public static boolean externalIronDustAvailable(){return!ItemTags.getAllTags().getTag(DUST).getValues().isEmpty();}public static boolean fallbackDustRequired(){return ModList.get().isLoaded("create")&&!externalIronDustAvailable();}}
